+      },
+      "Kokkos ERROR: attempting to call "
+      "parallel_reduce\\(\\) \\*\\*after\\*\\* Kokkos::finalize\\(\\) was "
+      "called. Concerns reduce_policy_ret_float with exec policy RangePolicy.");
+  EXPECT_DEATH(
