+  std::this_thread::sleep_for(10ms);
+  auto elapsed2 = std::as_const(t).seconds();
+  EXPECT_GE(elapsed2, .015);
+  EXPECT_GT(elapsed2, elapsed);
+
+  t.reset();
+  std::this_thread::sleep_for(5ms);
