+    //}
+    static_assert(!std::constructible_from<Kokkos::View<int *>,
+                                           decltype(a.data_handle()), int>);
+#endif
+  }
+};
+
+TEST(TEST_CATEGORY, view_ctor_data_handle) {
+  TestViewCtorDataHandle<
+      TEST_EXECSPACE>::test_view_data_handle_ctor_ref_counts();
+}
+
+}  // namespace

