+
+  auto h_v = Kokkos::create_mirror_view_and_copy(Kokkos::HostSpace{}, v);
+  bool data_preserved = true;
+
+  for (int i0 = 0; i0 < 4; ++i0) {
+    for (int i1 = 0; i1 < 5; ++i1) {
+      if (h_v(i0, i1) != 99) {
