+  ref[1]              = 1.5e-2;                   // (d2_in / u)
+  ref[2]              = 4.0 / 3.0 * 1.0e5 / gam;  // (x1 * u / gam)
+  ref[3]              = SType(-1.0);              // flag
+  ref[4]              = 1.0 / gam;                // h11
+  ref[5]              = h21;                      // h21
+  ref[6]              = 1.0e4 / (3.0 * gam);      // h12 / gam
+  ref[7]              = SType(1.0);               // h22
