+  d2_in  = SType(4.0e-2);
+  x1_in  = SType(1.0e5);
+  y1_in  = SType(10.0);
+  p1     = d1_in * x1_in;
+  p2     = d2_in * y1_in;
+  h11    = 5.0e-5;                             // (d1_in * x1_in) / (d2_in * y1_in)
+  h22    = 1.0e4;                              // (x1_in / y1_in)
+  u      = 1.5;                                // 1.0 + h11 * h22
+  ref[0] = 8.0 / 3.0 * 1.0e-2;                 // (d2_in / u)
+  ref[1] = 4.0 / 3.0 * 1.0e-10 * (gam * gam);  // (d1_in / u) * (gam * gam);
+  ref[2] = 15;                                 // (x1 * u)
+  ref[3] = SType(-1.0);                        // flag
+  ref[4] = h11;                                // h11
+  ref[5] = SType(-1.0) / gam;                  // 1.0 / gam
