+  d1_in  = SType(2.0e10);
+  d2_in  = SType(4.0e-2);
+  x1_in  = SType(1.0e-5);
+  y1_in  = SType(10.0);
+  p1     = d1_in * x1_in;
+  p2     = d2_in * y1_in;
+  h11    = 5.0e5;                             // (d1_in * x1_in) / (d2_in * y1_in)
+  h22    = 1.0e-6;                            // (x1_in / y1_in)
+  u      = 1.5;                               // 1.0 + h11 * h22
